from collections import deque

def transform(grid):
    """Fill background regions completely enclosed by the non-background outline with 4."""
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)
    outside = [[False] * w for _ in range(h)]
    q = deque()
    for r in range(h):
        for c in (0, w - 1):
            if grid[r][c] == background and not outside[r][c]:
                outside[r][c] = True
                q.append((r, c))
    for c in range(w):
        for r in (0, h - 1):
            if grid[r][c] == background and not outside[r][c]:
                outside[r][c] = True
                q.append((r, c))
    while q:
        r, c = q.popleft()
        for nr, nc in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)):
            if 0 <= nr < h and 0 <= nc < w and not outside[nr][nc] and grid[nr][nc] == background:
                outside[nr][nc] = True
                q.append((nr, nc))
    return [[4 if grid[r][c] == background and not outside[r][c] else grid[r][c]
             for c in range(w)] for r in range(h)]
